<script setup lang="ts">
import {numericColumnAlign} from './numericTableColumns'
import {useLocalPagination} from './localPagination'
import {useTableWidths as useListTableWidths} from './tableWidths'
const listWidths=useListTableWidths('LogisticsPanelLists')

import {can,firstAllowed} from './session'
import {ref,reactive,computed,onMounted,watch} from 'vue'
import {ElMessage,ElMessageBox} from 'element-plus'
import {api,session} from './session'
import {useTableWidths} from './tableWidths'
const widths=useTableWidths('LogisticsPanel')
const props=defineProps<{shipment?:any}>(),emit=defineEmits(['open-shipment'])
const tab=ref(firstAllowed('logistics',['channels', 'settlements', 'invoice', 'declaration'])),rows=ref<any[]>([]),channels=ref<any[]>([]),busy=ref(false),error=ref(''),q=ref(''),page=ref(1),pageSize=ref(25),total=ref(0)
const settlementMode=ref<'edit'|'settle'>('edit'),settledForm=ref(false)
const dialog=ref(''),editing=ref<number|null>(null),form=reactive<any>({}),file=ref<File>(),templates=ref<any[]>([]),preview=ref<any>(),map=reactive<any>({sheet:'',fields:{},columns:{},start_row:10,end_row:30}),mappingId=ref(0)
const shipmentRows=ref<any[]>([]),shipmentQuery=ref(''),shipmentPage=ref(1),shipmentPageSize=ref(25),shipmentTotal=ref(0),shipmentCtx=ref<any>(null)
const channelQuery=ref(''),channelOptions=ref<any>({countries:{},channels:[],tax_modes:[],last_mile_modes:[]})
const countryLabel=(value:string)=>channelOptions.value.countries[value]||value
const kind=computed(()=>tab.value==='invoice'?'invoice':'declaration')
const computedTotal=computed(()=>Number((settlementMode.value==='settle'||settledForm.value?form.actual_charge_weight:form.charge_weight)||0)*Number(form.unit_price||0)+['surcharge','clearance_fee','declaration_fee','miscellaneous'].reduce((s,k)=>s+Number(form[k]||0),0))
const money=(n:any)=>n==null?'—':Number(n).toFixed(2)
async function load(){busy.value=true;error.value='';try{channels.value=await api('/logistics/channels');channelOptions.value=await api('/logistics/options');if(tab.value==='channels')rows.value=channelQuery.value.trim()?await api('/logistics/channels?q='+encodeURIComponent(channelQuery.value.trim())):channels.value;else if(tab.value==='settlements'){const d=await api('/logistics/settlements?'+new URLSearchParams({q:q.value,page:String(page.value),page_size:String(pageSize.value)}));rows.value=d.rows;total.value=d.total}else rows.value=await api('/logistics/templates?kind='+kind.value)}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
watch(tab,()=>{page.value=1;load()});onMounted(load)
function openChannel(row?:any){editing.value=row?.id||null;Object.keys(form).forEach(k=>delete form[k]);Object.assign(form,{name:'',country:'',channel:'',price:0,transit:'',clearance_fee:0,declaration_fee:0,currency:'CNY',tax_mode:'',last_mile:'',...row});delete form.id;form.country=Object.entries(channelOptions.value.countries).find(([code,name])=>code===form.country||name===form.country)?.[0]||(form.country==='GB'?'UK':form.country);for(const k of ['price','clearance_fee','declaration_fee'])form[k]=Number(form[k]);dialog.value='channel'}
function copyChannel(row:any){openChannel(JSON.parse(JSON.stringify(row)));editing.value=null;delete form.revision}
async function saveChannel(){await save('/logistics/channels'+(editing.value?'/'+editing.value:''),form)}
async function save(path:string,body:any){busy.value=true;try{await api(path,body);dialog.value='';await load();ElMessage.success('已保存')}catch(e){ElMessage.error((e as Error).message)}finally{busy.value=false}}
async function remove(path:string,body:any={}){try{await ElMessageBox.confirm('确定删除这条记录？','删除');await api(path,body);await load()}catch(e){if(e instanceof Error)ElMessage.error(e.message)}}
async function findShipments(){try{const d=await api('/logistics/shipments?'+new URLSearchParams({q:shipmentQuery.value,page:String(shipmentPage.value),page_size:String(shipmentPageSize.value)}));shipmentRows.value=d.rows;shipmentTotal.value=d.total}catch(e){ElMessage.error((e as Error).message)}}
async function chooseShipment(row:any){try{shipmentCtx.value=await api('/logistics/shipment?'+new URLSearchParams({store:row.store,shipment_id:row.shipment_id}));form.store=row.store;form.shipment_id=row.shipment_id;form.charge_weight=shipmentCtx.value.weight==null?0:Number(shipmentCtx.value.weight)}catch(e){ElMessage.error((e as Error).message)}}
function chooseChannel(id:number){const c=channels.value.find(c=>c.id===id);if(c)Object.assign(form,{unit_price:Number(c.price),clearance_fee:Number(c.clearance_fee),declaration_fee:Number(c.declaration_fee)})}
async function openSettlement(row?:any,edit?:any,mode:'edit'|'settle'='edit'){settlementMode.value=mode;settledForm.value=edit?.status==='settled';editing.value=edit?.id||null;Object.keys(form).forEach(k=>delete form[k]);Object.assign(form,{revision:null,actual_charge_weight:null,store:'',shipment_id:'',channel_id:null,date:new Date().toLocaleDateString('sv-SE'),charge_weight:0,unit_price:0,surcharge:0,clearance_fee:0,declaration_fee:0,miscellaneous:0,total_override:null,note:''});shipmentCtx.value=null;dialog.value='settlement';if(edit){await chooseShipment(edit);for(const k of Object.keys(form))if(k in edit)form[k]=['actual_charge_weight','charge_weight','unit_price','surcharge','clearance_fee','declaration_fee','miscellaneous','total_override'].includes(k)&&edit[k]!=null?Number(edit[k]):edit[k]}else if(row)await chooseShipment(row);else await findShipments()}
async function saveSettlement(){
 if(!form.shipment_id||!form.channel_id){ElMessage.warning('请选择货件和物流渠道');return}
 if((settlementMode.value==='settle'||settledForm.value)&&!(Number(form.actual_charge_weight)>0)){ElMessage.warning('请填写大于0的实际收费重量');return}
 const suffix=settlementMode.value==='settle'?'/settle':''
 await save('/logistics/settlements'+(editing.value?'/'+editing.value:'')+suffix,{...form,total_override:settlementMode.value==='settle'||settledForm.value?null:form.total_override})
}
watch(()=>props.shipment,async row=>{if(row){tab.value='settlements';channels.value=await api('/logistics/channels');await openSettlement(row)}},{immediate:true})
function uploadTemplate(){Object.keys(form).forEach(k=>delete form[k]);Object.assign(form,{name:'',supplier:'',kind:kind.value});file.value=undefined;dialog.value='upload'}
async function upload(){if(!file.value){ElMessage.warning('请选择 Excel 模板');return}busy.value=true;try{if(file.value.size>15*1024*1024)throw Error('模板不能超过15MB');const bytes=new Uint8Array(await file.value.arrayBuffer());let raw='';for(let i=0;i<bytes.length;i+=8192)raw+=String.fromCharCode(...bytes.subarray(i,i+8192));const d=await api('/logistics/templates/upload',{...form,filename:file.value.name,content:btoa(raw)});await load();await editMap({id:d.id,mapping:{}})}catch(e){ElMessage.error((e as Error).message)}finally{busy.value=false}}
async function editMap(row:any){try{mappingId.value=row.id;preview.value=await api(`/logistics/templates/${row.id}/preview`);Object.assign(map,{sheet:preview.value.sheet,fields:{},columns:{},start_row:10,end_row:30,row_mode:preview.value.row_mode||'box',...row.mapping});dialog.value='mapping'}catch(e){ElMessage.error((e as Error).message)}}
async function sheetChanged(){preview.value=await api(`/logistics/templates/${mappingId.value}/preview?sheet=`+encodeURIComponent(map.sheet))}
async function saveMap(){const fields=Object.fromEntries(Object.entries(map.fields).filter(([,v])=>v)),columns=Object.fromEntries(Object.entries(map.columns).filter(([,v])=>v));await save(`/logistics/templates/${mappingId.value}/mapping`,{...map,fields,columns})}
const localPager=useLocalPagination(()=>tab.value==='settlements'?[]:rows.value)
</script>
<template><section class="panel hub"><el-radio-group v-model="tab"><el-radio-button v-if="can('logistics.channels')" value="channels">物流渠道</el-radio-button><el-radio-button v-if="can('logistics.settlements')" value="settlements">结算中心</el-radio-button><el-radio-button v-if="can('logistics.invoice')" value="invoice">发票中心</el-radio-button><el-radio-button v-if="can('logistics.declaration')" value="declaration">报关单</el-radio-button></el-radio-group>
<div class="hub-tools"><el-input v-if="tab==='channels'" v-model="channelQuery" placeholder="搜索货代名称" clearable style="width:200px" @keyup.enter="load" @clear="load"/><el-button v-if="tab==='channels'" @click="load">查询</el-button><el-input v-if="tab==='settlements'" v-model="q" placeholder="搜索 FBA 号 / 货代" clearable style="width:200px" @keyup.enter="page=1;load()"/><el-button @click="load">刷新</el-button><el-button v-if="can('logistics.'+tab,'operate')" type="primary" @click="tab==='channels'?openChannel():tab==='settlements'?openSettlement():uploadTemplate()">{{tab==='channels'?'新增物流渠道':tab==='settlements'?'新增结算':'上传 Excel 模板'}}</el-button><TableReset :table-key="'LogisticsPanel/'+tab"/></div><el-alert v-if="error" :title="error" type="error" :closable="false"/>
<template v-if="true"><el-table    :data="tab==='settlements'?rows:localPager.rows.value" v-loading="busy" border :data-width-key="'LogisticsPanel/'+tab" @header-dragend="(w:number,_:number,c:any)=>widths.resize(tab,w,c)">
<template v-if="tab==='channels'"><el-table-column  :width="widths.width(tab,key,140)" v-for="(label,key) in {name:'货代名称',country:'国家',channel:'渠道',tax_mode:'是否包税',last_mile:'尾端派送方式',price:'单价 /kg',currency:'币种',transit:'预计时效',clearance_fee:'清关费',declaration_fee:'报关费'}" :key="key" :prop="key" :label="label" :column-key="key"  :align="numericColumnAlign(label)"><template #default="{row}">{{key==='country'?countryLabel(row[key]):row[key]??'—'}}</template></el-table-column><el-table-column :column-key="'column-2'" :width="widths.width(tab,'channel-actions',200)" label="操作" fixed="right" ><template #default="{row}"><el-button link @click="openChannel(row)">编辑</el-button><el-button link type="primary" @click="copyChannel(row)">复制</el-button><el-button link type="danger" @click="remove('/logistics/channels/'+row.id+'/delete',{revision:row.revision})">删除</el-button></template></el-table-column></template>
<template v-else-if="tab==='settlements'"><el-table-column :column-key="'column-3'" :width="widths.width(tab,'column-3','170')" label="FBA号" ><template #default="{row}"><el-button link type="primary" @click="emit('open-shipment',row)">{{row.shipment_id}}</el-button></template></el-table-column><el-table-column column-key="status" label="状态" :width="widths.width(tab,'status',110)"><template #default="{row}"><el-tag :type="row.status==='settled'?'success':'info'">{{row.status==='settled'?'已结算':'未结算'}}</el-tag></template></el-table-column><el-table-column column-key="store" label="店铺" prop="store" :width="widths.width(tab,'store',120)"/><el-table-column :column-key="'column-4'" :width="widths.width(tab,'column-4',undefined)" label="货代名称 - 国家 - 渠道" min-width="240"><template #default="{row}">{{row.channel.name}} - {{countryLabel(row.channel.country)}} - {{row.channel.channel}}</template></el-table-column><el-table-column  :width="widths.width(tab,key,135)" v-for="(label,key) in {date:'日期',boxes:'箱数',charge_weight:'装箱单重量 kg',actual_charge_weight:'实际收费重量 kg',unit_price:'单价 /kg',surcharge:'附加费',clearance_fee:'清关费',declaration_fee:'报关费',miscellaneous:'杂费',total:'总价'}" :key="key" :prop="key" :label="label" :column-key="key"  :align="numericColumnAlign(label)"/><el-table-column :column-key="'channel.currency'" :width="widths.width(tab,'channel.currency','90')" label="币种" prop="channel.currency" /><el-table-column column-key="settled_by" label="结算人" :width="widths.width(tab,'settled_by',120)"><template #default="{row}">{{row.settled_by||'—'}}</template></el-table-column><el-table-column column-key="settled_at" label="结算时间" :width="widths.width(tab,'settled_at',190)"><template #default="{row}">{{row.settled_at?new Date(row.settled_at).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai',hour12:false}):'—'}}</template></el-table-column><el-table-column :column-key="'column-7'" :width="widths.width(tab,'settlement-actions',150)" label="操作" fixed="right" ><template #default="{row}"><el-button v-if="can('logistics.settlements','operate')" link @click="openSettlement(undefined,row)">编辑</el-button><el-button v-if="can('logistics.settlements','operate')" link type="primary" :disabled="row.status==='settled'" @click="openSettlement(undefined,row,'settle')">结算</el-button></template></el-table-column></template>
<template v-else><el-table-column :column-key="'name'" :width="widths.width(tab,'name',undefined)" label="模板名称" prop="name" min-width="200"/><el-table-column :column-key="'column-9'" :width="widths.width(tab,'column-9',undefined)" label="物流供应商" min-width="160"><template #default="{row}">{{row.supplier||'通用'}}</template></el-table-column><el-table-column :column-key="'column-10'" :width="widths.width(tab,'column-10','120')" label="字段配置" ><template #default="{row}">{{row.mapping?.sheet?'已配置':'待配置'}}</template></el-table-column><el-table-column :column-key="'column-11'" :width="widths.width(tab,'column-11','260')" label="操作" ><template #default="{row}"><el-button link type="primary" @click="editMap(row)">配置字段</el-button><a :href="`/api/logistics/templates/${row.id}/download`">下载模板</a><el-button link type="danger" @click="remove('/logistics/templates/'+row.id+'/delete')">删除</el-button></template></el-table-column></template></el-table></template><AppPagination v-if="tab==='settlements'" v-model:current-page="page" :total="total" @change="load" v-model:page-size="pageSize"/><AppPagination v-else v-model:current-page="localPager.page.value" v-model:page-size="localPager.pageSize.value" :total="localPager.total.value"/>
<el-dialog :model-value="dialog==='channel'" :title="editing?'编辑物流渠道':'新增物流渠道'" width="650px" @close="dialog=''"><el-form label-position="top"><div class="hub-grid"><el-form-item v-for="(label,key) in {name:'货代名称',transit:'预计时效',currency:'币种'}" :key="key" :label="label"><el-input v-model="form[key]"/></el-form-item><el-form-item label="国家"><el-select v-model="form.country" filterable placeholder="请选择国家" aria-label="物流国家"><el-option v-for="(name,code) in channelOptions.countries" :key="code" :value="code" :label="String(name)+' · '+code"/></el-select></el-form-item><el-form-item label="渠道"><el-select v-model="form.channel" placeholder="请选择渠道" aria-label="物流渠道"><el-option v-for="v in channelOptions.channels" :key="v" :value="v" :label="v"/></el-select></el-form-item><el-form-item label="是否包税"><el-select v-model="form.tax_mode" clearable placeholder="请选择" aria-label="是否包税"><el-option v-for="v in channelOptions.tax_modes" :key="v" :value="v" :label="v"/></el-select></el-form-item><el-form-item label="尾端派送方式"><el-select v-model="form.last_mile" clearable placeholder="请选择" aria-label="尾端派送方式"><el-option v-for="v in channelOptions.last_mile_modes" :key="v" :value="v" :label="v"/></el-select></el-form-item><el-form-item v-for="(label,key) in {price:'单价 /kg',clearance_fee:'清关费',declaration_fee:'报关费'}" :key="key" :label="label"><el-input-number v-model="form[key]" :min="0" :precision="2"/></el-form-item></div></el-form><template #footer><el-button @click="dialog=''">取消</el-button><el-button type="primary" :loading="busy" @click="saveChannel">保存</el-button></template></el-dialog>
<el-dialog :model-value="dialog==='settlement'" :title="settlementMode==='settle'?'确认物流结算':'编辑物流结算'" width="920px" @close="dialog=''"><template v-if="!form.shipment_id"><div class="hub-tools"><el-input v-model="shipmentQuery" placeholder="搜索 FBA 号" @keyup.enter="shipmentPage=1;findShipments()"/><el-button @click="shipmentPage=1;findShipments()">查找</el-button><TableReset table-key="LogisticsPanelLists/list-2"/></div><template v-if="true"><el-table data-width-key="LogisticsPanelLists/list-2" @header-dragend="(w:number,_:number,c:any)=>listWidths.resize('list-2',w,c)" @header-contextmenu="(c:any,e:MouseEvent)=>listWidths.resetColumn('list-2',c,e)" :data="shipmentRows"><el-table-column :column-key="'shipment_id'" :width="listWidths.width('list-2','shipment_id',undefined)" prop="shipment_id" label="FBA号"/><el-table-column :column-key="'store'" :width="listWidths.width('list-2','store',undefined)" prop="store" label="店铺"/><el-table-column :column-key="'name'" :width="listWidths.width('list-2','name',undefined)" prop="name" label="货件名称"/><el-table-column :column-key="'column-4'" :width="listWidths.width('list-2','column-4',undefined)" label="操作"><template #default="{row}"><el-button @click="chooseShipment(row)">选择</el-button></template></el-table-column></el-table></template><AppPagination v-model:current-page="shipmentPage" :total="shipmentTotal" @change="findShipments" v-model:page-size="shipmentPageSize"/></template><template v-else><p>{{form.shipment_id}} · {{form.store}} · 装箱单重量 {{shipmentCtx?.weight??'待同步'}} kg · {{shipmentCtx?.boxes??'待同步'}} 箱</p><el-form label-position="top"><div class="hub-grid"><el-form-item label="物流渠道"><el-select v-model="form.channel_id" filterable @change="chooseChannel"><el-option v-for="c in channels" :key="c.id" :value="c.id" :label="`${c.name} - ${countryLabel(c.country)} - ${c.channel} (${c.currency})`"/></el-select></el-form-item><el-form-item label="日期"><el-date-picker v-model="form.date" value-format="YYYY-MM-DD"/></el-form-item><el-form-item v-for="(label,key) in {charge_weight:'装箱单重量 kg',unit_price:'单价 /kg',surcharge:'附加费',clearance_fee:'清关费',declaration_fee:'报关费',miscellaneous:'杂费'}" :key="key" :label="label"><el-input-number v-model="form[key]" :min="0" :precision="2"/></el-form-item><el-form-item v-if="settlementMode==='settle'||settledForm" label="实际收费重量 kg" required><el-input-number v-model="form.actual_charge_weight" aria-label="实际收费重量 kg" :min="0.0001" :precision="4"/></el-form-item><el-form-item v-if="settlementMode!=='settle'&&!settledForm" :label="'计算总价 '+money(computedTotal)+'；手动总价（留空用计算值）'"><el-input-number v-model="form.total_override" :min="0" :precision="2" :controls="false"/></el-form-item><el-form-item v-if="settlementMode==='settle'||settledForm" label="结算总价"><strong class="settlement-total">{{money(computedTotal)}}</strong><span class="settlement-hint">实际收费重量 × 单价 ＋ 附加费 ＋ 清关费 ＋ 报关费 ＋ 杂费</span></el-form-item><el-form-item label="备注"><el-input v-model="form.note"/></el-form-item></div></el-form></template><template #footer><el-button @click="dialog=''">取消</el-button><el-button type="primary" :loading="busy" :disabled="!form.shipment_id" @click="saveSettlement">{{settlementMode==='settle'?'确认结算':'保存'}}</el-button></template></el-dialog>
<el-dialog :model-value="dialog==='upload'" title="上传 Excel 模板" width="560px" @close="dialog=''"><el-form label-position="top"><el-form-item label="模板名称"><el-input v-model="form.name"/></el-form-item><el-form-item :label="form.kind==='invoice'?'物流供应商（必填）':'物流供应商（留空为通用模板）'"><el-select v-model="form.supplier" filterable allow-create default-first-option clearable><el-option v-for="name in [...new Set(channels.map(c=>c.name))]" :key="name" :value="name" :label="name"/></el-select></el-form-item><input type="file" accept=".xlsx" @change="file=($event.target as HTMLInputElement).files?.[0]"/></el-form><template #footer><el-button type="primary" :loading="busy" @click="upload">上传并配置</el-button></template></el-dialog>
<el-dialog :model-value="dialog==='mapping'" title="配置模板字段与商品明细位置" width="min(1250px,96vw)" @close="dialog=''"><template v-if="preview"><div class="hub-tools"><el-select v-model="map.sheet" style="width:180px" @change="sheetChanged"><el-option v-for="s in preview.sheets" :value="s" :label="s"/></el-select><el-select v-model="map.row_mode" aria-label="发票明细排列" style="width:230px"><el-option value="box" label="每箱每商品一行"/><el-option value="sku" label="每商品合计一行（旧模板）"/></el-select><span>明细开始行（不含表头）</span><el-input-number v-model="map.start_row" aria-label="明细开始行" :min="1" :max="5000"/><span>明细结束行</span><el-input-number v-model="map.end_row" aria-label="明细结束行" :min="map.start_row" :max="5000"/></div><p>固定字段填写完整单元格地址（如 B4），商品明细只填写列字母（如 C），不要填写 C21。新模板按每箱每商品一行；申报数量为该商品箱内件数，申报总量为该 SKU 整票件数（各箱重复展示，不应相加）。箱号按 FBA号U000001 递增，同一混装箱的商品共用箱号和箱规。未配置的字段保留模板原内容。</p><el-alert title="例如：第 20 行为表头，开始行填 21；模板预留到第 30 行，结束行填 30，可放 10 行 SKU。中文名称填 C、英文名称填 D、申报单价填 E、申报数量填 F。" type="info" :closable="false"/><p class="mapping-hint">当前填写第 {{map.start_row}}～{{map.end_row}} 行，共 {{Math.max(0,map.end_row-map.start_row+1)}} 行；不会自动插入行。箱号、追踪编码、箱规或申报总量任一字段启用时会按箱展开；缺少完整装箱数据时提示补齐。旧模板保持原列映射，商品金额及 kg 重量旧字段可清空移除。清关url按货件目的国自动选择英国或德国链接。</p><div class="mapping-grid"><section class="mapping-fields"><h4>基本信息 · 填完整地址，例如 R18</h4><el-form-item v-for="(label,key) in preview.scalars" :label="String(label)"><el-input v-model="map.fields[key]" :aria-label="'基本信息：'+label" placeholder="如 B4"/></el-form-item></section><section class="mapping-fields"><h4>商品明细 · 基础资料 + 清关资料（填列字母）</h4><el-form-item v-for="(label,key) in preview.columns" :label="String(label)"><el-input v-model="map.columns[key]" :aria-label="'商品明细：'+label" placeholder="如 A"/></el-form-item></section><section class="template-preview"><h4>模板内容预览</h4><table><tr v-for="(row,n) in preview.rows" :key="n" :class="{'mapped-detail-row':Number(n)+1>=map.start_row&&Number(n)+1<=map.end_row}"><td v-for="c in row" :title="c.cell"><small>{{c.cell}}</small>{{c.value}}</td></tr></table></section></div></template><template #footer><el-button @click="dialog=''">取消</el-button><el-button type="primary" :loading="busy" @click="saveMap">保存配置</el-button></template></el-dialog></section></template>
<style scoped>.settlement-total{font-size:20px;color:#227660}.settlement-hint{display:block;width:100%;font-size:12px;color:#71867d}.hub{padding:16px}.hub-tools{display:flex;gap:12px;align-items:center;flex-wrap:wrap;margin:14px 0}.hub-grid{display:grid;grid-template-columns:1fr 1fr;gap:0 20px}.hub-grid .el-select{width:100%}.hub a{color:#227660;margin:0 10px}.mapping-grid{display:flex;flex-direction:column;gap:16px}.mapping-fields{display:grid;grid-template-columns:repeat(6,minmax(0,1fr));gap:0 12px}.mapping-fields h4{grid-column:1/-1}.mapping-fields :deep(.el-form-item){display:block}.mapping-fields :deep(.el-form-item__label){display:block;text-align:left}.template-preview h4{position:sticky;left:0}.template-preview{border:1px solid #dbe6e0;padding:12px}@media(max-width:900px){.mapping-fields{grid-template-columns:repeat(2,minmax(0,1fr))}}.template-preview{overflow:auto;max-height:650px}.template-preview table{border-collapse:collapse;font-size:12px}.template-preview td{border:1px solid #dbe6e0;min-width:80px;padding:6px;white-space:pre-wrap}.mapped-detail-row{background:#edf6f0}.mapping-hint{font-size:12px;color:#6d8277;line-height:1.8}.template-preview small{display:block;color:#94a59b}.hub :deep(.el-pagination){margin-top:16px}</style>
